module luggage_speed_solver (input clk, input rst_n, input start, input [5:0] num_luggage, input [7:0] belt_length, input [31:0] positions [0:7], output reg [31:0] max_speed, output reg valid, output reg no_fika); reg [31:0] low, high, best_speed, mid; reg [31:0] reg_positions [0:7]; reg [7:0] reg_belt_length; reg [5:0] reg_num_luggage; reg [6:0] iteration_count; reg [1:0] state; reg valid_found; localparam LOW_INIT = 6554; localparam HIGH_INIT = 10 << 16; localparam THRESHOLD = 1 << 16; localparam MAX_ITER = 40; function automatic int check_collision; input int test_speed, input int num, input int pos_arr [], input int L_fixed; output automatic int has_collision; reg [31:0] p_i, p_j, delta, dt; reg [31:0] p_i_mod, p_j_mod; integer i, j; has_collision = 0; for (i=0; i<num; i=i+1) begin for (j=i+1; j<num; j=j+1) begin delta = pos_arr[i] - pos_arr[j]; if (delta < 0) delta = -delta; if (test_speed == 0) dt = 0; else dt = delta / test_speed; p_i = pos_arr[i] + (test_speed * dt); p_j = pos_arr[j] + (test_speed * dt); p_i_mod = p_i % L_fixed; if (p_i_mod < 0) p_i_mod += L_fixed; p_j_mod = p_j % L_fixed; if (p_j_mod < 0) p_j_mod += L_fixed; delta = p_i_mod - p_j_mod; if (delta < 0) delta = -delta; if (delta < THRESHOLD || (L_fixed - delta) < THRESHOLD) begin has_collision = 1; return has_collision; end end end return has_collision; endfunction always @(posedge clk) begin if (!rst_n) begin state <= 0; low <= LOW_INIT; high <= HIGH_INIT; best_speed <= 0; iteration_count <= 0; valid_found <= 0; reg_belt_length <= belt_length; reg_num_luggage <= num_luggage; reg_positions[0] <= positions[0]; reg_positions[1] <= positions[1]; reg_positions[2] <= positions[2]; reg_positions[3] <= positions[3]; reg_positions[4] <= positions[4]; reg_positions[5] <= positions[5]; reg_positions[6] <= positions[6]; reg_positions[7] <= positions[7]; state <= 0; max_speed <= 0; valid <= 0; no_fika <= 0; end else begin case(state) 0: begin if (start) begin reg_belt_length <= belt_length; reg_num_luggage <= num_luggage; reg_positions[0] <= positions[0]; reg_positions[1] <= positions[1]; reg_positions[2] <= positions[2]; reg_positions[3] <= positions[3]; reg_positions[4] <= positions[4]; reg_positions[5] <= positions[5]; reg_positions[6] <= positions[6]; reg_positions[7] <= positions[7]; state <= 1; max_speed <= 0; valid <= 0; no_fika <= 0; end else begin state <= 0; max_speed <= 0; valid <= 0; no_fika <= 0; end end 1: begin if (reg_num_luggage == 0) begin state <= 3; max_speed <= 0; valid <= 0; no_fika <= 1; end else begin low <= LOW_INIT; high <= HIGH_INIT; iteration_count <= 0; best_speed <= 0; valid_found <= 0; state <= 2; max_speed <= 0; valid <= 0; no_fika <= 0; end end 2: begin if (iteration_count < MAX_ITER) begin iteration_count <= iteration_count + 1; mid = (low + high) >> 1; int coll; coll = check_collision(mid, reg_num_luggage, reg_positions, reg_belt_length << 16); if (!coll) begin if (best_speed == 0 || mid > best_speed) begin best_speed <= mid; valid_found <= 1; end low <= mid; end else begin high <= mid - 1; end if (iteration_count == MAX_ITER) begin state <= 3; end max_speed <= 0; valid <= 0; no_fika <= 0; end else begin state <= 3; max_speed <= 0; valid <= 0; no_fika <= 0; end end 3: begin if (valid_found) begin max_speed <= best_speed; valid <= 1; no_fika <= 0; end else begin max_speed <= 0; valid <= 0; no_fika <= 1; end state <= 3; endcase end endmodule